eaa92e6e","row":{"idea":"Set union, intersection and absorption","focus":{"release":"20260929-est1-idea-expansion","takeaway":"Key skill: Set union, intersection and absorption.","collections":["unique"],"math_format":"latex","bank_occurrences":1},"active":true,"lesson":"Logic and sets","difficulty":"medium","programmes":["est"],"fingerprint":"75f192e033d2aa85657b44e7ec21ce07","question_id":"a4c68116-825f-4a37-9f49-1c20eaa92e6e"},"hash":"d8da29dc2407a3c24c97d6b4d26dce29"}],"weighted_hash":"46244517c46948eb8aba6dc5a81998d3","mapping":{"02ac14b4-f84e-6e9f-1ab3-1427f41cdef7":"fd8a640f-d351-7cbc-e455-9f2f51709e79","92118004-2f60-6326-dab8-e6ad8b7911e7":"53c77113-7a68-6837-4af9-b5d4594962cb","331de3d6-88c5-6cf4-3195-fd9efc2019d6":"389099ff-c93c-5290-9688-3fc4ea0f5ffa","dc220155-bbb4-ddc2-6f65-aa31fc55dd7a":"91126e02-c74e-55ea-a4ce-0157f5cbf3fe"}},"adaptation":{"id":"91126e02-c74e-55ea-a4ce-0157f5cbf3fe","track_id":"est","topic":"Ratios, percentages and unit conversion","difficulty":"medium","type":"mcq","stem":"X and Y are inversely proportional. When x = 4, y = 5. What is y\u00b2 when x = 3, rounded to two decimal places?","choices":[{"key":"A","text":"44.44"},{"key":"B","text":"6.67"},{"key":"C","text":"25.00"},{"key":"D","text":"9.00"}],"correct":"A","explanation":"Inverse proportion means xy is constant. Here xy = 4 \u00d7 5 = 20. At x = 3, y = 20/3, so y\u00b2 = 400/9 = 44.444\u2026 . Rounded to two decimal places, this is 44.44, choice A.","assets":{"source":"Eng Abdelrahman Ghoneem \u2014 reviewed instructor adaptation","source_question_id":"GH-REVIEW-20261005-inverse-proportion","content_origin":"instructor_adaptation","source_ids_adapted":["dc220155-bbb4-ddc2-6f65-aa31fc55dd7a"],"curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Inverse proportion and squared values","lesson_taxonomy_version":"20261005","verified_release":"20261005-remaining-skill-review","answer_review_status":"independently_solved"}},"holds":{"02ac14b4-f84e-6e9f-1ab3-1427f41cdef7":"Stored point A(\u22123,44) and B(1,\u22122) give slope \u221211.5, absent from the choices. Preserve the original until source coordinates are verified.","92118004-2f60-6326-dab8-e6ad8b7911e7":"The question asks to simplify A(x) but provides no definition of A(x); option powers are OCR-corrupted. Preserve the source until its missing expression is verified.","331de3d6-88c5-6cf4-3195-fd9efc2019d6":"The new mean is 910/57 \u2248 15.9649, or 16.0 to one decimal place. No stored choice is correct; 15.9 is not the rounded result.","dc220155-bbb4-ddc2-6f65-aa31fc55dd7a":"The requested power is stored as y* and the choices contain OCR annotation fragments. The original exponent must be verified; a separately authored squared-value adaptation is available."},"changes":[{"id":"33a219c7-c1fa-5f58-a55c-bf2c22cccb85","title":"EST I \u2014 Statistics and data analysis \u2014 Source practice 33a219c7","question_ids":["389099ff-c93c-5290-9688-3fc4ea0f5ffa"]},{"id":"409a1c30-4a28-420e-a090-fb858513a09a","title":"EST I \u2014 Mixed skills \u2014 Source practice 409a1c30","question_ids":["fd8a640f-d351-7cbc-e455-9f2f51709e79","038993d1-b753-c0ba-9570-01f8ab6124e0","0a95bfb6-30df-c3c0-d33c-e5a15adfd76c","0c8b1b7f-bcd6-11b2-0db3-de291d7e7df4","0d8d4ea3-be1f-bc84-5db9-316ab2d458d7","0e673807-c4b8-3ff2-8a89-3f504a5912ce","0f903815-6ab3-765a-f5af-2e1c3e13fdf6","0fb55610-9253-9fb0-6f08-8a415b6edece","119f2069-177f-fd3c-3606-035c46264b67","163b33a8-34e6-0fd3-f8ab-87a5683e7064","1890be68-8663-1492-3d35-35cb4f360677","199d6976-2b71-905e-9aec-889720bf2f80","1ea4fe04-4a95-fdea-7323-77b5f1558942","1f157430-f01c-294b-c4ef-36929bf5ddf8","1f72859c-385b-f913-17bc-b4b8c5cd941a","20546978-a28f-0222-64e6-d904469699de","2764f3de-d5e5-a200-4547-723cfb85514d","2805d575-dd4d-9d99-caed-11e92c8f4319","2b6279f9-5d84-c436-70d9-15a48e7e1395","2da6a0db-dc8d-da18-6b03-abb5a6ba324e"]},{"id":"854ac600-ebe2-42c1-b4b2-07ef629cc570","title":"EST I \u2014 Mixed skills \u2014 Source practice 854ac600","question_ids":["7c28c31f-43b2-d0aa-e2c5-f4f4bafba8b4","7dde3e4f-583b-331c-ed99-7ac7f9a8aae7","7f231779-be71-2f87-fd43-50ba14636043","8389f658-e4d8-87f5-69ed-76d6c6a12a19","855228b6-6cf0-30d9-bbaa-c3222fd51a33","8a1fbba4-ac9f-1c5a-99e1-d4838576e40e","8b144389-f978-f4ef-f233-6c6155e883cf","8d657bd9-2af8-6080-a05f-648df6a8e08c","8e5cf006-fe41-7bae-e676-e2354a6916a9","8f837c16-8096-c128-2509-410a190123ba","9053b06a-14e0-86b2-1616-31fc90726ae2","91a56f20-a3cb-dfc4-74dc-483e5c31e0c3","9210d3e2-d311-4739-94dc-722187eb7726","53c77113-7a68-6837-4af9-b5d4594962cb","92209c3f-418e-e955-7232-5dda771812e6","9221d0a8-55b7-3c0c-9628-5e9cec68556f","92f77626-cf96-fa75-d172-b57c96a2bb24","93290e68-223f-4f69-8e55-646f49598d24","935147fe-dd28-39df-b93c-0aca8a27c43b","954cc02c-362c-e738-45e7-3f14a6baa73b"]},{"id":"44f78447-035b-4fe7-886b-210307b1e6b4","title":"EST I \u2014 Mixed skills \u2014 Source practice 44f78447","question_ids":["bb35af6f-dc1e-4600-14ee-bef2842b7a08","c279cde1-ee45-6874-b30c-b937462859d5","c3f89d73-eead-c715-ff52-152a275fdd7c","cce52abe-c3f7-b219-9ce0-595c47a6e573","ce7da225-b505-2b6d-8475-5b0334030662","d2f717a4-ec5f-294b-fa31-d5622b829735","d62887a6-b09c-b8b0-690d-bfcbb25cd067","d8f3d9c0-7810-a4bc-1906-8d2034b41084","d9eaf651-01cd-43e5-9584-347818be4b43","91126e02-c74e-55ea-a4ce-0157f5cbf3fe","ddf9abdb-fe34-8936-159c-0329934198af","de3bd434-fbf5-cc4b-8128-98d693754c81","dfcdf4e1-e3ea-b087-d0a1-f45011f89210","e005a2dc-43ee-db63-b7b9-7abe96e36d8a","e03d05c9-65fc-b6f9-fcc8-59b05b5c48b6","e281cdae-aef5-657c-69e9-554747f3d822","e773194a-5f49-6be4-2600-4c9790f93f05","e7862c9b-d69c-1e79-6895-4ce92428e341","e851ee2a-cfce-dded-0dab-559461b37b4d","eb22a74a-de0b-ffe1-75f8-cda019471cc4"]},{"id":"d017f2ad-153b-48ba-b5c4-ba0698c2ee3b","title":"EST I \u2014 Mixed skills \u2014 Source practice d017f2ad","question_ids":["0009abf2-0392-09f4-5263-4cf7b050595f","ff77c776-a33d-c23f-442c-abe35ff84a02"]}]}'::jsonb; x jsonb; q_ public.questions; k_ public.question_keys; e_ public.exams; a_ jsonb; n_ integer;
begin
 -- Refuse stale packets, changed audiences, new attempts or unexpected revision membership.
 for x in select * from jsonb_array_elements(data_->'decisions') loop
  select * into q_ from public.questions where id=(x->>'id')::uuid;
  select * into k_ from public.question_keys where question_id=q_.id;
  if md5(jsonb_build_object('q',to_jsonb(q_),'k',to_jsonb(k_))::text) is distinct from x->>'hash' then raise exception 'Concurrent question change: %',x->>'id'; end if;
  insert into portal_private.skill_review_20261005_backup values('question',q_.id,jsonb_build_object('q',to_jsonb(q_),'k',to_jsonb(k_)),null);
 end loop;
 if (select count(*) from public.revision_items where question_id in(select (j.value->>'id')::uuid from jsonb_array_elements(data_->'decisions') j(value)))<>jsonb_array_length(data_->'guards'->'revisions') then raise exception 'Concurrent revision membership'; end if;
 for x in select * from jsonb_array_elements(data_->'guards'->'revisions') loop
  if (select md5(to_jsonb(r)::text) from public.revision_items r where question_id=(x->>'id')::uuid) is distinct from x->>'hash' then raise exception 'Concurrent revision change'; end if;
 end loop;
 for x in select * from jsonb_array_elements(data_->'guards'->'exams') loop
  select * into e_ from public.exams where id=(x->'exam'->>'id')::uuid;
  if md5(to_jsonb(e_)::text) is distinct from x->>'hash' then raise exception 'Concurrent exam change'; end if;
  if exists(select 1 from public.attempts where exam_id=e_.id) then raise exception 'Exam now has student history'; end if;
  if (select md5(coalesce(jsonb_agg(to_jsonb(a) order by id),'[]'::jsonb)::text) from public.assignments a where exam_id=e_.id) is distinct from x->>'assignment_hash' then raise exception 'Concurrent assignment change'; end if;
  insert into portal_private.skill_review_20261005_backup values('exam',e_.id,jsonb_build_object('exam',to_jsonb(e_),'assignment_hash',x->>'assignment_hash'),null);
 end loop;
 if (select md5(jsonb_build_object('q',to_jsonb(q),'k',to_jsonb(k))::text) from public.questions q join public.question_keys k on k.question_id=q.id where q.id='389099ff-c93c-5290-9688-3fc4ea0f5ffa') is distinct from data_->'guards'->>'weighted_hash' then raise exception 'Concurrent weighted adaptation change'; end if;
 if exists(select 1 from public.exams e where e.is_published and e.question_ids && array(select key::uuid from jsonb_each_text(data_->'holds')) and e.id not in(select (j.value->>'id')::uuid from jsonb_array_elements(data_->'changes') j(value))) then raise exception 'Unexpected published use of a held question'; end if;
 if exists(select 1 from public.revision_items where active and question_id in(select key::uuid from jsonb_each_text(data_->'holds'))) then raise exception 'Unexpected active revision use'; end if;
 -- Only taxonomy fields change for the 146 records. These fields are excluded from revision fingerprints.
 for x in select * from jsonb_array_elements(data_->'decisions') loop
  update public.questions set topic=x->>'topic',assets=coalesce(assets,'{}'::jsonb)||jsonb_build_object('curriculum_lesson',x->>'topic','lesson_subtopic',x->>'skill','lesson_original_topic',coalesce(assets->>'lesson_original_topic',topic),'lesson_taxonomy_version','20261005') where id=(x->>'id')::uuid;
 end loop;
 for x in select jsonb_build_object('id',key,'reason',value) from jsonb_each_text(data_->'holds') loop
  update public.questions set assets=assets||jsonb_build_object('release_hold_reason',x->>'reason','answer_review_status','blocked_source_verification','replacement_question_id',data_->'guards'->'mapping'->>(x->>'id')) where id=(x->>'id')::uuid;
 end loop;
 a_:=data_->'adaptation';
 insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets) values((a_->>'id')::uuid,a_->>'track_id',a_->>'topic',a_->>'difficulty',a_->>'type',a_->>'stem',a_->'choices',a_->'assets');
 insert into public.question_keys(question_id,correct,explanation) values((a_->>'id')::uuid,a_->'correct',a_->>'explanation');
 insert into portal_private.skill_review_20261005_backup values('adaptation',(a_->>'id')::uuid,a_,null);
 for x in select * from jsonb_array_elements(data_->'changes') loop
  update public.exams set title=x->>'title',question_ids=array(select value::uuid from jsonb_array_elements_text(x->'question_ids')) where id=(x->>'id')::uuid;
  if not (select portal_private.exam_content_ready(question_ids,track_id) from public.exams where id=(x->>'id')::uuid) then raise exception 'Corrected exam is not eligible'; end if;
 end loop;
 if exists(select 1 from public.revision_items r join public.questions q on q.id=r.question_id join public.question_keys k on k.question_id=q.id where r.active and r.fingerprint is distinct from public.revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)) then raise exception 'Stale active revision fingerprint'; end if;
 update portal_private.skill_review_20261005_backup b set after_hash=case when kind='exam' then (select md5(to_jsonb(e)::text) from public.exams e where e.id=b.id) else (select md5(jsonb_build_object('q',to_jsonb(q),'k',to_jsonb(k))::text) from public.questions q join public.question_keys k on k.question_id=q.id where q.id=b.id) end;
end $review$;
commit;
